import React, { useEffect } from "react";
import ReactDOM from "react-dom";
import { Carousel } from "../components/ui/Carousel";
import "../styles/ProjectModal.css";

// New component for just the images/carousel
const ProjectModalImages = ({ slides, image, title }) => {
  if (slides && slides.length > 0) {
    const carouselItems = slides.map(slide => ({
      image: slide.src,
      name: slide.title,
      text: slide.button
    }));
    return <Carousel items={carouselItems} baseWidth={500} autoplay={false} />;
  }
  return <img src={image} alt={title} className="modal-image" />;
};

const ProjectModal = ({ open, onClose, project }) => {
  useEffect(() => {
    if (open) {
      document.body.classList.add('modal-open');
    } else {
      document.body.classList.remove('modal-open');
    }
    return () => document.body.classList.remove('modal-open');
  }, [open]);

  if (!open || !project) return null;

  const modalContent = (
    <div className="modal-backdrop" onClick={onClose}>
      <div className="modal-content" onClick={e => e.stopPropagation()}>
        <button className="modal-close" onClick={onClose}>&times;</button>
        {/* Only images/carousel re-renders on nav arrow click */}
        <ProjectModalImages slides={project.slides} image={project.image} title={project.title} />
        <h2 className="modal-title">{project.title}</h2>
        <p className="modal-description">{project.description}</p>
        <div className="modal-buttons">
          {project.demo && (
            <a href={project.demo} target="_blank" rel="noopener noreferrer" className="modal-btn">View Project Demo</a>
          )}
          {project.source && (
            <a href={project.source} target="_blank" rel="noopener noreferrer" className="modal-btn">View Source</a>
          )}
        </div>
      </div>
    </div>
  );

  return ReactDOM.createPortal(modalContent, document.body);
};

export default ProjectModal;
